package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.suit.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import java.util.*;
/** Resource catalog available in the field; normal/deepslate ores are one choice. */
public final class SuitOreScreen extends Screen {
 private final Screen parent;private List<SuitOres.Resource> catalog=List.of();private String query="";private int page;private int x,y,w=328,h=226;
 public SuitOreScreen(Screen parent){super(Component.literal("Сканер ресурсов"));this.parent=parent;}
 @Override protected void init(){x=(width-w)/2;y=(height-h)/2;var search=new EditBox(font,x+12,y+35,w-24,18,Component.literal("Название ресурса / mod:id"));search.setMaxLength(128);search.setValue(query);search.setResponder(q->{query=q;page=0;rebuildCatalog();rebuildWidgets();});addRenderableWidget(search);setInitialFocus(search);setFocused(search);rebuildCatalog();int start=page*12;for(int i=0;i<12&&start+i<catalog.size();i++){var r=catalog.get(start+i);int row=i/3,col=i%3;var b=new SuitUi.Control("    "+new ItemStack(r.icon()).getHoverName().getString(),x+12+col*102,y+62+row*29,98,25,()->SuitClient.action("ore_filter",r.id()),()->selected(r));b.setTooltip(Tooltip.create(Component.literal(new ItemStack(r.icon()).getHoverName().getString()+" · вариантов: "+r.blocks().size()+"\n"+String.join(", ",r.blocks()))));addRenderableWidget(b);}
 addRenderableWidget(SuitUi.button("Все руды",x+12,y+185,90,20,()->SuitClient.action("ore_filter","*")));addRenderableWidget(SuitUi.button("←",x+109,y+185,24,20,()->{page=Math.max(0,page-1);rebuildWidgets();}));addRenderableWidget(SuitUi.button("→",x+137,y+185,24,20,()->{if((page+1)*12<catalog.size())page++;rebuildWidgets();}));addRenderableWidget(SuitUi.button("Готово",x+w-91,y+185,79,20,this::onClose));}
 private void rebuildCatalog(){String q=query.toLowerCase(Locale.ROOT);catalog=SuitOres.catalog().stream().filter(r->r.id().toLowerCase(Locale.ROOT).contains(q)||new ItemStack(r.icon()).getHoverName().getString().toLowerCase(Locale.ROOT).contains(q)||r.blocks().stream().anyMatch(b->b.contains(q))).toList();}
 private boolean selected(SuitOres.Resource r){var filter=SuitClient.wornData().contents().ores();return filter.isEmpty()||filter.contains(r.id())||r.blocks().stream().anyMatch(filter::contains);}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float dt){SuitUi.panel(g,x,y,w,h);g.text(font,title,x+12,y+12,SuitUi.ACCENT);g.text(font,"Ресурс → все варианты руды · радиус 25 м",x+12,y+24,SuitUi.MUTED);super.extractRenderState(g,mx,my,dt);for(int i=0;i<12&&page*12+i<catalog.size();i++)g.item(new ItemStack(catalog.get(page*12+i).icon()),x+16+(i%3)*102,y+66+(i/3)*29);g.text(font,"Пустой список выбранного = искать всё",x+12,y+211,SuitUi.MUTED);g.text(font,(page+1)+"/"+Math.max(1,(catalog.size()+11)/12),x+175,y+191,SuitUi.TEXT);}
 @Override public void onClose(){minecraft.setScreenAndShow(parent);}
 @Override public boolean isPauseScreen(){return false;}
}
